import type { Companhia, Experiencia, Humor } from "@/features/noite/opcoes";
import type { ClassificacaoBR, OrdemDescoberta } from "@/lib/tmdb/tipos";

/**
 * Tabelas de mapeamento das respostas para os filtros do TMDB.
 * Espelham as tabelas de `SPEC/2026-11-18-wizard-noite.md`, que o cliente revisa.
 */

/** IDs de gênero de filme do TMDB usados no wizard. */
const G = {
  acao: 28,
  animacao: 16,
  aventura: 12,
  comedia: 35,
  crime: 80,
  drama: 18,
  ficcao: 878,
  guerra: 10752,
  historia: 36,
  misterio: 9648,
  romance: 10749,
  terror: 27,
  thriller: 53,
} as const;

/** Um "tom" da experiência: os gêneros exigidos juntos e o nome que vai no motivo. */
export type Tom = { nome: string; generos: number[] };

/** Tons de cada experiência, em ordem ("Não é o clima" passa ao seguinte), e exclusões fixas. */
export const TONS: Record<Experiencia, { tons: Tom[]; sem?: number[] }> = {
  rir: {
    tons: [
      { nome: "comédia leve", generos: [G.comedia] },
      { nome: "comédia romântica", generos: [G.comedia, G.romance] },
      { nome: "comédia de aventura", generos: [G.comedia, G.aventura] },
    ],
    sem: [G.terror, G.thriller, G.crime, G.guerra],
  },
  emocionar: {
    tons: [
      { nome: "drama", generos: [G.drama] },
      { nome: "romance", generos: [G.romance, G.drama] },
      { nome: "drama de época", generos: [G.drama, G.historia] },
    ],
  },
  susto: {
    tons: [
      { nome: "terror", generos: [G.terror] },
      { nome: "terror de mistério", generos: [G.terror, G.misterio] },
      { nome: "terror de ficção científica", generos: [G.terror, G.ficcao] },
    ],
  },
  tenso: {
    tons: [
      { nome: "suspense", generos: [G.thriller] },
      { nome: "policial", generos: [G.crime, G.thriller] },
      { nome: "mistério", generos: [G.misterio] },
    ],
  },
  pensar: {
    tons: [
      { nome: "ficção científica", generos: [G.ficcao] },
      { nome: "mistério", generos: [G.misterio, G.drama] },
      { nome: "drama para refletir", generos: [G.drama] },
    ],
  },
  distrair: {
    tons: [
      { nome: "aventura", generos: [G.aventura] },
      { nome: "ação", generos: [G.acao] },
      { nome: "animação", generos: [G.animacao] },
    ],
    sem: [G.terror, G.guerra],
  },
};

/** Quantos tons cada experiência tem (o `tom` da URL vai de 0 a TOTAL_TONS - 1). */
export const TOTAL_TONS = 3;

type AjusteHumor = {
  duracaoMax?: number;
  ordem?: OrdemDescoberta;
  lancadoAte?: string;
  /** Excluídos, salvo se o tom atual pedir o gênero. */
  sem?: number[];
};

const PESADOS = [G.terror, G.thriller, G.guerra];

export const AJUSTES_HUMOR: Record<Humor, AjusteHumor> = {
  cansado: { duracaoMax: 110, ordem: "popularidade" },
  animado: {},
  "pra-baixo": { sem: PESADOS },
  nostalgico: { lancadoAte: "2005-12-31" },
  ansioso: { sem: PESADOS },
  "de-boa": {},
};

/** Classificação máxima em "família com crianças" (proposta da issue #2). */
export const CLASSIFICACAO_FAMILIA: ClassificacaoBR = "12";

export const AJUSTES_COMPANHIA: Record<
  Companhia,
  { classificacaoMax?: ClassificacaoBR; ordem?: OrdemDescoberta }
> = {
  sozinho: {},
  "a-dois": {},
  familia: { classificacaoMax: CLASSIFICACAO_FAMILIA },
  amigos: { ordem: "popularidade" },
};

/** Piso de qualidade, sempre aplicado. */
export const PISO = { notaMin: 6.5, votosMin: 300 } as const;

export const ORDEM_PADRAO: OrdemDescoberta = "nota";

/** "Muito longo": quanto encurtar, o mínimo e a base quando a duração é desconhecida. */
export const DURACAO_TROCA = { reducao: 20, minima: 80, base: 120 } as const;

/** "Até que horas?": com menos minutos que isso, não há filme a sugerir. */
export const TEMPO_MINIMO = 60;
import {
  CLIMAS,
  climaSchema,
  MAX_TROCAS,
  type Clima,
  MOTIVOS_TROCA,
  type Pergunta,
} from "@/features/metricas/eventos";
import { DURACAO_TROCA, TOTAL_TONS } from "@/features/noite/mapeamento";
import { HORAS_LIMITE, PERGUNTAS, type HoraLimite } from "@/features/noite/opcoes";
import { minutosAte } from "@/features/noite/termina";
import { limparIds } from "@/features/surpresa/memoria";

export type MotivoTroca = (typeof MOTIVOS_TROCA)[number];

/** Tudo o que o wizard sabe, guardado só na URL de `/noite`. */
export type EstadoNoite = {
  respostas: Partial<Clima>;
  tom: number;
  /** Limite de duração vindo de "Muito longo". */
  duracaoMax: number | null;
  /** IDs já mostrados nesta sessão do wizard. */
  vistos: number[];
  trocas: number;
  /** "Até que horas?": a hora escolhida, ou `null` para "Tanto faz". Sempre junto de `tempo`. */
  ate: HoraLimite | null;
  /** Minutos que faltavam até `ate`, calculados no navegador da pessoa. */
  tempo: number | null;
};

export const ROTA_NOITE = "/noite";
export const MAX_VISTOS_NOITE = 50;
const DURACAO_MAXIMA_URL = 600;
const TEMPO_MAXIMO_URL = 24 * 60;

export const ESTADO_INICIAL: EstadoNoite = {
  respostas: {},
  tom: 0,
  duracaoMax: null,
  vistos: [],
  trocas: 0,
  ate: null,
  tempo: null,
};

type Busca = Record<string, string | string[] | undefined>;

function texto(valor: string | string[] | undefined): string | undefined {
  return typeof valor === "string" ? valor : undefined;
}

function inteiro(valor: string | string[] | undefined, min: number, max: number): number | null {
  const bruto = texto(valor);
  if (!bruto || !/^\d{1,4}$/.test(bruto)) return null;
  const numero = Number(bruto);
  return numero >= min && numero <= max ? numero : null;
}

function resposta<P extends Pergunta>(pergunta: P, valor: string | undefined) {
  return (CLIMAS[pergunta] as readonly string[]).includes(valor ?? "")
    ? (valor as Clima[P])
    : undefined;
}

/** Lê o estado dos `searchParams` de `/noite`; valores inválidos são ignorados. */
export function lerEstado(busca: Busca): EstadoNoite {
  const respostas: Partial<Clima> = {};
  for (const { chave, parametro } of PERGUNTAS) {
    const valor = resposta(chave, texto(busca[parametro]));
    if (valor) Object.assign(respostas, { [chave]: valor });
  }
  const vistos = (texto(busca.vistos) ?? "").split(",").filter(Boolean).map(Number);
  const hora = inteiro(busca.ate, 0, 23);
  const ate = HORAS_LIMITE.find((h) => h === hora) ?? null;
  const tempo = inteiro(busca.tempo, 0, TEMPO_MAXIMO_URL);
  // A hora e os minutos só valem juntos: sem um deles, é "Tanto faz".
  const horario = ate !== null && tempo !== null ? { ate, tempo } : { ate: null, tempo: null };

  return {
    respostas,
    tom: inteiro(busca.tom, 0, TOTAL_TONS - 1) ?? 0,
    duracaoMax: inteiro(busca.max, DURACAO_TROCA.minima, DURACAO_MAXIMA_URL),
    vistos: limparIds(vistos).slice(-MAX_VISTOS_NOITE),
    trocas: inteiro(busca.trocas, 0, MAX_TROCAS) ?? 0,
    ...horario,
  };
}

/** A próxima pergunta sem resposta, na ordem das telas, ou `null` com as três respondidas. */
export function proximaPergunta(estado: EstadoNoite): (typeof PERGUNTAS)[number] | null {
  return PERGUNTAS.find(({ chave }) => !estado.respostas[chave]) ?? null;
}

/** As três respostas, quando completas e válidas. */
export function respostasCompletas(estado: EstadoNoite): Clima | null {
  const resultado = climaSchema.safeParse(estado.respostas);
  return resultado.success ? resultado.data : null;
}

/** URL de `/noite` para o estado, só com os parâmetros que fogem do padrão. */
export function urlDaNoite(estado: EstadoNoite): string {
  const busca = new URLSearchParams();
  for (const { chave, parametro } of PERGUNTAS) {
    const valor = estado.respostas[chave];
    if (valor) busca.set(parametro, valor);
  }
  if (estado.ate !== null && estado.tempo !== null) {
    busca.set("ate", String(estado.ate));
    busca.set("tempo", String(estado.tempo));
  }
  if (estado.tom > 0) busca.set("tom", String(estado.tom));
  if (estado.duracaoMax !== null) busca.set("max", String(estado.duracaoMax));
  if (estado.vistos.length > 0) busca.set("vistos", estado.vistos.join(","));
  if (estado.trocas > 0) busca.set("trocas", String(estado.trocas));
  const consulta = busca.toString().replaceAll("%2C", ",");
  return consulta ? `${ROTA_NOITE}?${consulta}` : ROTA_NOITE;
}

/** URL com mais uma resposta: o cartão de cada opção do wizard é um link para ela. */
export function urlComResposta<P extends Pergunta>(
  estado: EstadoNoite,
  pergunta: P,
  valor: Clima[P],
): string {
  return urlDaNoite({ ...estado, respostas: { ...estado.respostas, [pergunta]: valor } });
}

/**
 * "Até que horas?": o mesmo estado com a hora escolhida e os minutos que faltam no relógio
 * `agora` (o do navegador). `null` é "Tanto faz". Não é troca: o resto do estado fica igual.
 */
export function comHorario(estado: EstadoNoite, hora: HoraLimite | null, agora: Date): EstadoNoite {
  if (hora === null) return { ...estado, ate: null, tempo: null };
  return { ...estado, ate: hora, tempo: minutosAte(hora, agora) };
}

/** Encurta o limite de duração depois de "Muito longo" (tabela de precedência da spec). */
function encurtar(atual: number | null, duracaoRecusada: number | null): number {
  const { reducao, minima, base } = DURACAO_TROCA;
  const novo = (duracaoRecusada ?? atual ?? base) - reducao;
  return Math.max(minima, Math.min(novo, atual ?? novo));
}

/**
 * Estado da próxima rodada depois de "Esse não": os filmes mostrados entram em `vistos`,
 * o motivo ajusta o tom ou a duração e `trocas` sobe. `null` quando já não há trocas.
 * `mostrados[0]` é o destaque recusado.
 */
export function proximaRodada(
  estado: EstadoNoite,
  motivo: MotivoTroca,
  mostrados: { id: number; duracaoMin: number | null }[],
): EstadoNoite | null {
  if (estado.trocas >= MAX_TROCAS) return null;
  const vistos = limparIds([...estado.vistos, ...mostrados.map(({ id }) => id)]);

  return {
    ...estado,
    vistos: vistos.slice(-MAX_VISTOS_NOITE),
    trocas: estado.trocas + 1,
    tom: motivo === "nao-e-o-clima" ? (estado.tom + 1) % TOTAL_TONS : estado.tom,
    duracaoMax:
      motivo === "muito-longo"
        ? encurtar(estado.duracaoMax, mostrados[0]?.duracaoMin ?? null)
        : estado.duracaoMax,
  };
}

/** URL da próxima rodada para cada motivo de "Esse não", ou `null` sem trocas restantes. */
export function urlsDaTroca(
  estado: EstadoNoite,
  mostrados: { id: number; duracaoMin: number | null }[],
): Record<MotivoTroca, string> | null {
  const urls = {} as Record<MotivoTroca, string>;
  for (const motivo of MOTIVOS_TROCA) {
    const proxima = proximaRodada(estado, motivo, mostrados);
    if (!proxima) return null;
    urls[motivo] = urlDaNoite(proxima);
  }
  return urls;
}

"use client";

import { RotateCw } from "lucide-react";
import Link from "next/link";

import { Button, buttonVariants } from "@/components/ui/button";

/** O TMDB (ou o banco) falhou: refazer as perguntas não resolveria, então oferece tentar de novo. */
export default function ErroNoite({ retry }: { error: Error; retry: () => void }) {
  return (
    <section className="mx-auto flex w-full max-w-3xl flex-1 flex-col items-start gap-4 px-4 py-16">
      <h1 className="text-3xl tracking-tight text-balance">
        Não deu para montar a sua noite agora.
      </h1>
      <p className="text-muted-foreground">
        Não conseguimos buscar os filmes agora. Costuma ser passageiro: tente de novo em instantes.
      </p>
      <div className="flex flex-wrap gap-3">
        <Button size="lg" onClick={() => retry()}>
          <RotateCw aria-hidden="true" />
          Tentar de novo
        </Button>
        <Link href="/dashboard" className={buttonVariants({ size: "lg", variant: "outline" })}>
          Ir para o início
        </Link>
      </div>
    </section>
  );
}
import { SessaoNoite } from "@/features/noite/components/sessao-noite";

/** Mantém a sessão do wizard (eventos de início, conclusão e abandono) entre as telas. */
export default function NoiteLayout({ children }: LayoutProps<"/noite">) {
  return <SessaoNoite>{children}</SessaoNoite>;
}
import type { Metadata } from "next";
import { redirect } from "next/navigation";
import { Suspense } from "react";

import { exigirUsuario } from "@/features/auth/sessao";
import { AteQueHoras } from "@/features/noite/components/ate-que-horas";
import { PerguntaNoite } from "@/features/noite/components/pergunta-noite";
import { EsqueletoNoite, RecomendacaoNoite } from "@/features/noite/components/recomendacao-noite";
import {
  lerEstado,
  proximaPergunta,
  respostasCompletas,
  urlDaNoite,
} from "@/features/noite/estado";
import { obterPreferencias } from "@/features/preferencias/consultas";

export const metadata: Metadata = { title: "O que ver hoje?" };

/**
 * Wizard "O que ver hoje?" (SPEC/2026-11-18-wizard-noite.md). Todo o estado está na URL:
 * sem as três respostas, mostra a próxima pergunta; com elas, a recomendação da rodada,
 * com o "Até que horas?" opcional acima (SPEC/2026-11-18-noite-ate-que-horas.md).
 */
export default async function NoitePage({ searchParams }: PageProps<"/noite">) {
  await exigirUsuario();
  const preferencias = await obterPreferencias();
  if (!preferencias) redirect("/onboarding");

  const estado = lerEstado(await searchParams);
  const pergunta = proximaPergunta(estado);
  const respostas = respostasCompletas(estado);

  return (
    <div className="mx-auto flex w-full max-w-3xl flex-1 flex-col gap-8 px-4 py-8">
      {pergunta && <PerguntaNoite estado={estado} pergunta={pergunta} />}
      {respostas && (
        <div className="flex flex-col gap-6">
          <AteQueHoras estado={estado} />
          {/* A chave mostra o esqueleto de novo a cada troca, em vez da rodada anterior. */}
          <Suspense key={urlDaNoite(estado)} fallback={<EsqueletoNoite />}>
            <RecomendacaoNoite respostas={respostas} estado={estado} perfil={preferencias} />
          </Suspense>
        </div>
      )}
    </div>
  );
}
import type { Clima } from "@/features/metricas/eventos";
import type { FilmeNaTela } from "@/features/noite/components/filme-destaque";
import { ResultadoNoite } from "@/features/noite/components/resultado-noite";
import { SemNoite } from "@/features/noite/components/sem-noite";
import { SemTempo } from "@/features/noite/components/sem-tempo";
import { obterNoite } from "@/features/noite/consultas";
import { urlsDaTroca, type EstadoNoite } from "@/features/noite/estado";
import { TEMPO_MINIMO } from "@/features/noite/mapeamento";
import type { FilmeDaNoite, PerfilNoite } from "@/features/noite/recomendar";

/** Só os campos que a tela usa: elenco, parecidos e o resto do TMDB ficam no servidor. */
export function paraTela({ filme, provedor, motivo }: FilmeDaNoite): FilmeNaTela {
  const { id, titulo, ano, posterPath, sinopse, duracaoMin, trailerYoutube } = filme;
  return { id, titulo, ano, posterPath, sinopse, duracaoMin, trailerYoutube, motivo, provedor };
}

/**
 * Busca a rodada no servidor. Sem tempo até o "Até que horas?", nem consulta o TMDB.
 * Sem filme, oferece refazer; TMDB fora do ar vai ao `error.tsx`.
 */
export async function RecomendacaoNoite({
  respostas,
  estado,
  perfil,
}: {
  respostas: Clima;
  estado: EstadoNoite;
  perfil: PerfilNoite;
}) {
  const { ate, tempo } = estado;
  if (ate !== null && tempo !== null && tempo < TEMPO_MINIMO) {
    return <SemTempo estado={estado} ate={ate} tempo={tempo} />;
  }

  const resultado = await obterNoite(respostas, estado, perfil);
  if (!resultado) return <SemNoite />;

  // "Esse não" recusa tudo o que está na tela; o destaque vem primeiro ("Muito longo" usa a duração dele).
  const mostrados = [resultado.destaque, ...resultado.opcoes].map(({ filme }) => filme);
  return (
    <ResultadoNoite
      respostas={respostas}
      trocas={estado.trocas}
      destaque={paraTela(resultado.destaque)}
      opcoes={resultado.opcoes.map(paraTela)}
      proximas={urlsDaTroca(estado, mostrados)}
    />
  );
}

/** Enquanto o TMDB responde: o formato do destaque, sem conteúdo. */
export function EsqueletoNoite() {
  return (
    <div role="status" className="flex flex-col gap-5">
      <p className="text-muted-foreground">Procurando o filme da sua noite…</p>
      <div className="flex gap-4 sm:gap-6">
        <div className="bg-muted aspect-[2/3] w-28 shrink-0 animate-pulse rounded-lg sm:w-44" />
        <div className="flex flex-1 flex-col gap-3">
          <div className="bg-muted h-8 w-3/4 animate-pulse rounded" />
          <div className="bg-muted h-4 w-1/3 animate-pulse rounded" />
          <div className="bg-muted h-4 w-1/2 animate-pulse rounded" />
        </div>
      </div>
    </div>
  );
}
"use client";

import { useEffect, useState } from "react";

import { VouVerEsse } from "@/features/como-foi/components/vou-ver-esse";
import { MAX_TROCAS, type Clima } from "@/features/metricas/eventos";
import { CompartilharNoite } from "@/features/noite/components/compartilhar-noite";
import { EsseNao } from "@/features/noite/components/esse-nao";
import { FilmeDestaque, type FilmeNaTela } from "@/features/noite/components/filme-destaque";
import { OpcaoNoite } from "@/features/noite/components/opcao-noite";
import { useSessaoNoite } from "@/features/noite/components/sessao-noite";
import type { MotivoTroca } from "@/features/noite/estado";

type Props = {
  respostas: Clima;
  /** Trocas já feitas nesta sessão (0 na primeira recomendação). */
  trocas: number;
  destaque: FilmeNaTela;
  /** As 2 opções menores, depois de uma troca. */
  opcoes: FilmeNaTela[];
  /** URL da próxima rodada por motivo de "Esse não", ou `null` no limite. */
  proximas: Record<MotivoTroca, string> | null;
};

/**
 * Tela do resultado: o destaque e as opções, cada um com "Vou ver esse!", e "Esse não".
 * Na primeira rodada, conclui o wizard. Depois da escolha, só fica a confirmação do escolhido,
 * com o "Compartilhar".
 */
export function ResultadoNoite({ respostas, trocas, destaque, opcoes, proximas }: Props) {
  const { concluir, marcarEscolha } = useSessaoNoite();
  const [escolhido, setEscolhido] = useState<number | null>(null);

  useEffect(() => {
    if (trocas === 0) concluir(respostas);
  }, [concluir, respostas, trocas]);

  const vouVer = (filme: FilmeNaTela) =>
    (escolhido === null || escolhido === filme.id) && (
      <>
        <VouVerEsse
          tmdbId={filme.id}
          titulo={filme.titulo}
          trocas={trocas}
          aoEscolher={() => {
            setEscolhido(filme.id);
            marcarEscolha();
          }}
        />
        {escolhido === filme.id && (
          <CompartilharNoite
            tmdbId={filme.id}
            titulo={filme.titulo}
            duracaoMin={filme.duracaoMin}
          />
        )}
      </>
    );

  return (
    <div className="flex flex-col gap-10">
      <FilmeDestaque
        filme={destaque}
        acoes={
          <div className="flex flex-col gap-3 sm:flex-row sm:items-start">
            {vouVer(destaque)}
            {escolhido === null && (
              <EsseNao
                proximas={proximas}
                trocasRestantes={MAX_TROCAS - trocas}
                destaque={destaque}
              />
            )}
          </div>
        }
      />
      {opcoes.length > 0 && (
        <section aria-labelledby="ou-talvez" className="flex flex-col gap-3">
          <h2 id="ou-talvez" className="text-xl tracking-tight">
            Ou talvez
          </h2>
          <ul className="flex flex-col gap-3">
            {opcoes.map((filme) => (
              <li key={filme.id}>
