import { randomUUID } from "node:crypto";

import { createClient } from "@supabase/supabase-js";

import type { Database } from "@/lib/supabase/database.types";

/**
 * Valores do Supabase local (`supabase start`). São públicos e iguais em toda
 * instalação da CLI, não são segredos. Podem ser trocados por variáveis de ambiente.
 */
export const SUPABASE_LOCAL = {
  url: process.env.SUPABASE_LOCAL_URL ?? "http://127.0.0.1:54321",
  publishableKey:
    process.env.SUPABASE_LOCAL_PUBLISHABLE_KEY ?? "sb_publishable_ACJWlzQHlZjBrEguHvfOxg_3BJgxAaH",
};

export const SENHA_TESTE = "filme1234";

/** Email único por chamada, para os testes não dependerem uns dos outros. */
export function emailAleatorio(prefixo = "teste") {
  return `${prefixo}-${randomUUID()}@filmecerto.test`;
}

/** Cliente sem sessão persistida: cada um representa um usuário diferente. */
export function novoCliente() {
  return createClient<Database>(SUPABASE_LOCAL.url, SUPABASE_LOCAL.publishableKey, {
    auth: { persistSession: false, autoRefreshToken: false },
  });
}

/** Cria um usuário com perfil e devolve o cliente já autenticado como ele. */
export async function criarUsuario(nome = "Usuária Teste") {
  const cliente = novoCliente();
  const email = emailAleatorio();
  const { data, error } = await cliente.auth.signUp({
    email,
    password: SENHA_TESTE,
    options: { data: { nome } },
  });
  if (error || !data.user) throw error ?? new Error("signUp não devolveu usuário");
  return { cliente, id: data.user.id, email };
}
import { beforeAll, describe, expect, it } from "vitest";

import { criarUsuario } from "../../support/supabase-local";

describe("RLS das escolhas da noite", () => {
  let a: Awaited<ReturnType<typeof criarUsuario>>;
  let b: Awaited<ReturnType<typeof criarUsuario>>;
  let idDeA: number;

  beforeAll(async () => {
    a = await criarUsuario("Usuária A");
    b = await criarUsuario("Usuário B");
  });

  it("o usuário grava, lê e atualiza a própria escolha, com tipo filme por padrão", async () => {
    const gravada = await a.cliente
      .from("escolhas_noite")
      .insert({ tmdb_id: 550, titulo: "Clube da Luta" })
      .select("id, tipo, usuario_id, vezes_perguntado, respondido_em")
      .single();
    expect(gravada.error).toBeNull();
    expect(gravada.data).toMatchObject({
      tipo: "filme",
      usuario_id: a.id,
      vezes_perguntado: 0,
      respondido_em: null,
    });
    idDeA = gravada.data!.id;

    const atualizada = await a.cliente
      .from("escolhas_noite")
      .update({ vezes_perguntado: 1, perguntado_em: new Date().toISOString() })
      .eq("id", idDeA)
      .select("vezes_perguntado");
    expect(atualizada.data).toEqual([{ vezes_perguntado: 1 }]);
  });

  it("outro usuário não lê nem altera a escolha", async () => {
    expect((await b.cliente.from("escolhas_noite").select("id")).data).toEqual([]);

    const alteracao = await b.cliente
      .from("escolhas_noite")
      .update({ respondido_em: new Date().toISOString() })
      .eq("id", idDeA)
      .select("id");
    expect(alteracao.data).toEqual([]);

    const deA = await a.cliente.from("escolhas_noite").select("respondido_em").eq("id", idDeA);
    expect(deA.data).toEqual([{ respondido_em: null }]);
  });

  it("ninguém grava escolha em nome de outra pessoa", async () => {
    const { error } = await a.cliente
      .from("escolhas_noite")
      .insert({ usuario_id: b.id, tmdb_id: 13, titulo: "Forrest Gump" });
    expect(error?.code).toBe("42501");
  });

  it("o banco recusa ID zero, mais de 2 perguntas e tipo fora do enum", async () => {
    const idZero = await a.cliente.from("escolhas_noite").insert({ tmdb_id: 0, titulo: "X" });
    expect(idZero.error?.code).toBe("23514");

    const perguntas = await a.cliente
      .from("escolhas_noite")
      .insert({ tmdb_id: 1, titulo: "X", vezes_perguntado: 3 });
    expect(perguntas.error?.code).toBe("23514");

    const tipo = await a.cliente
      .from("escolhas_noite")
      .insert({ tmdb_id: 1, titulo: "X", tipo: "novela" as never });
    expect(tipo.error?.code).toBe("22P02");
  });
});

import { expect, type Page } from "@playwright/test";

import { SENHA_TESTE } from "../support/supabase-local";

export async function cadastrar(page: Page, nome: string, email: string) {
  await page.goto("/cadastro");
  await page.getByLabel("Nome").fill(nome);
  await page.getByLabel("Email").fill(email);
  await page.getByLabel("Senha", { exact: true }).fill(SENHA_TESTE);
  await page.getByLabel("Confirme a senha").fill(SENHA_TESTE);
  await page.getByRole("main").getByRole("button", { name: "Criar conta" }).click();
}

export async function entrar(page: Page, email: string, senha = SENHA_TESTE) {
  await page.getByLabel("Email").fill(email);
  await page.getByLabel("Senha").fill(senha);
  await page.getByRole("main").getByRole("button", { name: "Entrar" }).click();
}

export async function sair(page: Page) {
  await page.getByRole("banner").getByRole("button", { name: "Menu do usuário" }).click();
  await page.getByRole("menuitem", { name: "Sair" }).click();
  await expect(page).toHaveURL("/");
}

/**
 * Conclui o wizard com os gêneros dados (padrão: Ação + Drama), filmes médios e toda semana,
 * pulando os passos opcionais (gêneros evitados, streamings e filmes).
 */
export async function concluirOnboarding(page: Page, generos = ["Ação", "Drama"]) {
  await expect(page).toHaveURL("/onboarding");
  const main = page.getByRole("main");
  for (const genero of generos) {
    await main.getByRole("button", { name: genero, exact: true }).click();
  }
  await main.getByRole("button", { name: "Próximo" }).click();
  await main.getByRole("button", { name: "Pular" }).click();
  await main.getByRole("radio", { name: "Médios (90 a 120 min)" }).check();
  await main.getByRole("button", { name: "Próximo" }).click();
  await main.getByRole("radio", { name: "Toda semana" }).check();
  await main.getByRole("button", { name: "Próximo" }).click();
  await main.getByRole("button", { name: "Pular" }).click();
  await main.getByRole("button", { name: "Pular" }).click();
  await main.getByRole("button", { name: "Concluir" }).click();
  // Salvar espera as sugestões dos passos 6 e 7 (as Server Actions rodam uma por vez) e o dashboard.
  await expect(page).toHaveURL("/dashboard", { timeout: 15_000 });
}

/** Títulos das seções do dashboard, na ordem da página. */
export async function titulosDasSecoes(page: Page) {
  return page.getByRole("main").locator("section > h2").allTextContents();
}

