"use client";

import { Share2 } from "lucide-react";
import { useState, useSyncExternalStore } from "react";

import { Button, buttonVariants } from "@/components/ui/button";
import { linkWhatsApp, mensagemDaNoite, urlDoFilme } from "@/features/noite/compartilhar";
import { aCadaMeioMinuto } from "@/features/noite/components/termina-as";

const ESTILO = "h-12 px-6 text-base";

/** O suporte à Web Share não muda enquanto a página está aberta. */
const semMudancas = () => () => {};
const temWebShare = () => typeof navigator.share === "function";

/**
 * Depois do "Vou ver esse!": avisa quem vai assistir junto, com "Hoje vamos ver {título},
 * termina às {hora}" e o link do filme (SPEC/2026-11-18-noite-compartilhar.md). Usa a
 * folha de compartilhamento do aparelho e, sem ela, um link do WhatsApp. Não grava nada.
 */
export function CompartilharNoite({
  tmdbId,
  titulo,
  duracaoMin,
}: {
  tmdbId: number;
  titulo: string;
  duracaoMin: number | null;
}) {
  const webShare = useSyncExternalStore(semMudancas, temWebShare, () => false);
  // O href acompanha o relógio, como o "Começando agora, termina às…" da tela.
  const mensagem = useSyncExternalStore(
    aCadaMeioMinuto,
    () => mensagemDaNoite(titulo, duracaoMin, new Date()),
    () => null,
  );
  const [falhou, setFalhou] = useState(false);
  if (mensagem === null) return null;

  const url = urlDoFilme(window.location.origin, tmdbId);

  async function compartilhar() {
    try {
      await navigator.share({ text: mensagemDaNoite(titulo, duracaoMin, new Date()), url });
    } catch (erro) {
      // Cancelar a folha de compartilhamento não é erro.
      if (erro instanceof DOMException && erro.name === "AbortError") return;
      setFalhou(true);
    }
  }

  if (webShare && !falhou) {
    return (
      <Button variant="outline" size="lg" className={ESTILO} onClick={compartilhar}>
        <Share2 aria-hidden="true" />
        Compartilhar
      </Button>
    );
  }

  return (
    <a
      href={linkWhatsApp(mensagem, url)}
      target="_blank"
      rel="noopener noreferrer"
      className={buttonVariants({ variant: "outline", size: "lg", className: ESTILO })}
    >
      <Share2 aria-hidden="true" />
      Compartilhar no WhatsApp
    </a>
  );
}
import Link from "next/link";

import { buttonVariants } from "@/components/ui/button";
import { ROTA_NOITE } from "@/features/noite/estado";

/** Nenhum filme passou pelos filtros, pelo perfil e pelo que já foi mostrado. */
export function SemNoite() {
  return (
    <section aria-labelledby="sem-noite" className="flex flex-col items-start gap-4 py-8">
      <h1 id="sem-noite" className="text-3xl tracking-tight text-balance">
        Não achamos nada para essa noite
      </h1>
      <p className="text-muted-foreground">
        Com essas respostas, e sem repetir o que você já viu, não sobrou nenhum filme. Que tal
        tentar outras respostas?
      </p>
      <Link href={ROTA_NOITE} className={buttonVariants({ size: "lg" })}>
        Refazer as perguntas
      </Link>
    </section>
  );
}
import type { ReactNode } from "react";

import {
  anoEDuracao,
  PosterNoite,
  type FilmeNaTela,
} from "@/features/noite/components/filme-destaque";
import { TerminaAs } from "@/features/noite/components/termina-as";

/** Uma das 2 opções menores que aparecem depois de "Esse não". `acao` é o "Vou ver esse!". */
export function OpcaoNoite({ filme, acao }: { filme: FilmeNaTela; acao?: ReactNode }) {
  return (
    <article
      aria-labelledby={`opcao-${filme.id}`}
      className="border-border bg-card flex gap-4 rounded-xl border p-3"
    >
      <PosterNoite filme={filme} className="w-20 sm:w-24" />
      <div className="flex min-w-0 flex-1 flex-col gap-1.5">
        <h3 id={`opcao-${filme.id}`} className="leading-tight font-medium break-words">
          {filme.titulo}
        </h3>
        <p className="text-muted-foreground text-sm">
