      <FilmeDestaque filme={destaque} acoes={vouVer(destaque)} />
      {opcoes.length > 0 && (
        <section aria-labelledby="ou-talvez" className="flex flex-col gap-3">
          <h2 id="ou-talvez" className="text-xl tracking-tight">
